def _chamber(taus, theta, hold, x, times):
    kernel = -np.expm1(-times[:, None] / taus)
    frac = np.array([0.22659303, 0.58418078])
    profile = kernel @ (frac * taus) + (1 - frac.sum()) * times
    score = theta[2] + x @ theta[3:]
